<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { useI18n } from 'vue-i18n'
import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import DatePicker from 'primevue/datepicker'
import AsyncContent from '@/components/common/AsyncContent.vue'; import BaseChart from '@/components/charts/BaseChart.vue'; import MetricCard from '@/components/common/MetricCard.vue'; import PageHeader from '@/components/common/PageHeader.vue'; import { useAsyncData } from '@/composables/useAsyncData'; import { getAnalytics } from '@/services/workspace'

const {t}=useI18n(); const range=ref([new Date(2026,6,1),new Date(2026,6,15)]); const {data,loading,error,load}=useAsyncData(getAnalytics)
const trend=computed(()=>({grid:{left:35,right:12,top:20,bottom:25},tooltip:{trigger:'axis'},xAxis:{type:'category',data:t('analytics.weeks').split(',')},yAxis:{type:'value'},series:[{type:'line',smooth:true,data:data.value?.trend||[],lineStyle:{color:'#4f6bed',width:3},areaStyle:{color:'rgba(79,107,237,.12)'}}]}))
const channels=computed(()=>({tooltip:{trigger:'item'},legend:{bottom:0},series:[{type:'pie',radius:['48%','72%'],data:(data.value?.channels||[]).map(item=>({value:item.value,name:t(item.nameKey)}))}]}))
onMounted(load)
</script>

<template><PageHeader :title="$t('analytics.title')" :description="$t('analytics.description')"><template #actions><DatePicker v-model="range" selection-mode="range" :manual-input="false" show-icon /><Button :label="$t('analytics.export')" icon="pi pi-download" outlined /></template></PageHeader><AsyncContent :loading="loading" :error="error" :empty="!data" @retry="load"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard :label="$t('analytics.visits')" value="25,883" helper="+12.6%" icon="pi pi-eye" /><MetricCard :label="$t('analytics.users')" value="8,429" helper="+8.4%" icon="pi pi-users" tone="success" /><MetricCard :label="$t('analytics.conversion')" value="7.2%" helper="+1.1%" icon="pi pi-bolt" tone="warning" /><MetricCard :label="$t('analytics.duration')" :value="$t('analytics.durationValue')" :helper="$t('analytics.durationChange')" icon="pi pi-clock" tone="violet" /></div><div class="mt-3 grid gap-3 xl:grid-cols-[1.4fr_.8fr]"><section class="workspace-panel"><div class="panel-heading"><h2>{{ $t('analytics.trend') }}</h2></div><BaseChart :option="trend" :summary="$t('analytics.trendSummary')" /></section><section class="workspace-panel"><div class="panel-heading"><h2>{{ $t('analytics.channels') }}</h2></div><BaseChart :option="channels" :summary="$t('analytics.channelsSummary')" /></section></div><section class="workspace-panel mt-3"><div class="panel-heading"><h2>{{ $t('analytics.sourceDetails') }}</h2></div><DataTable :value="data?.rows"><Column :header="$t('analytics.source')"><template #body="{data:item}">{{ $t(item.sourceKey) }}</template></Column><Column field="visits" :header="$t('analytics.visits')" /><Column field="conversion" :header="$t('analytics.conversion')" /><Column field="change" :header="$t('analytics.change')" /></DataTable></section></AsyncContent></template>
